def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    obstacles = set(observation.get('obstacles', []))
    resources = observation.get('resources', [])
    opponent_x, opponent_y = observation.get('opponent_position', (x, y))

    def safe(pos):
        return 0 <= pos[0] < width and 0 <= pos[1] < height and pos not in obstacles

    dx, dy = 0, 0
    # Prioritize moving away from opponent if close
    ox, oy = opponent_x, opponent_y
    if abs(ox - x) + abs(oy - y) <= 2:
        if ox > x and safe((x - 1, y)):
            return [-1, 0]
        if ox < x and safe((x + 1, y)):
            return [1, 0]
        if oy > y and safe((x, y - 1)):
            return [0, -1]
        if oy < y and safe((x, y + 1)):
            return [0, 1]
    # Move towards nearest resource if exists
    if resources:
        res = min(resources, key=lambda r: abs(r[0]-x)+abs(r[1]-y))
        dx_res = res[0] - x
        dy_res = res[1] - y
        if abs(dx_res) > abs(dy_res):
            move_x = 1 if dx_res > 0 else -1
            if safe((x + move_x, y)):
                return [move_x, 0]
        else:
            move_y = 1 if dy_res > 0 else -1
            if safe((x, y + move_y)):
                return [0, move_y]
    # Else, move randomly to safe position
    for move in [(-1,0), (1,0), (0,-1), (0,1)]:
        nx, ny = x + move[0], y + move[1]
        if safe((nx, ny)):
            return [move[0], move[1]]
    # No move possible, stay in place
    return [0, 0]
